// First-launch sign-in screen. GitHub App sign-in is THE path (ADR 0020): the
// PAT route is no longer advertised here — it's a hidden, transitional
// beta-tester channel reachable only by directly navigating to /setup (personal
// access only, never an org seat; slated for removal once App auth is universal).

import { useNavigate } from '@tanstack/react-router';
import { ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { GithubMark } from '../auth/GithubMark';
import { PyorMark } from '../auth/PyorMark';
import { NoCodeSeenNote } from '../auth/NoCodeSeenNote';
import { PyorWindow } from '../ui/PyorWindow';

interface Props {
  fluid?: boolean;
  width?: number;
  height?: number;
}

export function WelcomeScreen({ fluid = false, width = 920, height = 640 }: Props) {
  const navigate = useNavigate();
  return (
    <PyorWindow
      width={width}
      height={height}
      title="Pyor"
      subtitle="Sign in"
      fluid={fluid}
      hideStatusBar
      flushLeft
    >
      <div className="flex flex-1 items-center justify-center overflow-auto bg-panel px-8 py-10">
        <div className="w-full max-w-[400px] text-center">
          <div className="mb-5 flex justify-center">
            <PyorMark size={48} />
          </div>
          <h1 className="font-display text-[22px] font-semibold tracking-tight text-foreground">
            Sign in to Pyor
          </h1>
          <p className="mx-auto mt-2 max-w-[360px] text-[13px] leading-relaxed text-muted-foreground">
            Pyor reads your pull requests, diffs and notifications straight from
            GitHub. Sign in to get started — your code never touches our
            servers.
          </p>

          <div className="mt-7">
            <Button
              className="h-11 w-full gap-2.5 rounded-lg text-sm font-semibold"
              onClick={() => void navigate({ to: '/connect' })}
            >
              <GithubMark className="!size-[18px]" />
              Sign in with GitHub
            </Button>
            <div className="mt-2.5 flex items-center justify-center gap-1.5 text-[11.5px] text-muted-foreground">
              <ShieldCheck className="size-3.5 text-pyor-pass" />
              Verified account · you pick the repos · revoke anytime
            </div>
          </div>

          <NoCodeSeenNote className="mx-auto mt-8 max-w-[360px] text-left" />
        </div>
      </div>
    </PyorWindow>
  );
}
